def backfill_alert_state_lifecycle(apps, schema_editor):
    AlertState = apps.get_model("alerts", "AlertState")
    open_states = {"queued", "sent", "escalated"}
    for state in AlertState.objects.select_related("alert_config").iterator():
        due_at = None
        escalation_count = 1 if state.state == "escalated" else 0
        last_escalated_at = state.updated_at if state.state == "escalated" else None
        if state.state in open_states:
            delay = (
                state.alert_config.escalation_timeout
                if state.state == "escalated"
                else state.alert_config.tat_for_escalation
            )
            due_at = state.updated_at + (
                delay or datetime.timedelta()
            )
        AlertState.objects.filter(pk=state.pk).update(
            created_at=state.updated_at,
            escalation_due_at=due_at,
            escalation_count=escalation_count,
            last_escalated_at=last_escalated_at,
        )

    duplicate_groups = (
        AlertState.objects.filter(state__in=open_states)
        .values("alert_config_id", "instance_ref")
        .annotate(row_count=Count("pk"))
        .filter(row_count__gt=1)
    )
    for group in duplicate_groups.iterator():
        duplicates = AlertState.objects.filter(
            alert_config_id=group["alert_config_id"],
            instance_ref=group["instance_ref"],
            state__in=open_states,
        ).order_by("-updated_at", "-pk")
        for duplicate in duplicates[1:]:
            duplicate.state = "closed"
            duplicate.escalation_due_at = None
            duplicate.save(update_fields=["state", "escalation_due_at"])


